class Solution {
    public int shortestUnit(String s) {
        int n = s.length();
        int[] fail = new int[n];
        for (int i = 1, k = 0; i < n; i++) {
            while (k > 0 && s.charAt(i) != s.charAt(k)) k = fail[k - 1];
            if (s.charAt(i) == s.charAt(k)) k++;
            fail[i] = k;
        }
        int p = n - fail[n - 1];
        return n % p == 0 ? p : n;
    }
}

