int shortestUnit(char* s) {
    int n = strlen(s);
    int* fail = calloc(n, sizeof(int));
    for (int i = 1, k = 0; i < n; i++) {
        while (k > 0 && s[i] != s[k]) k = fail[k - 1];
        if (s[i] == s[k]) k++;
        fail[i] = k;
    }
    int p = n - fail[n - 1];
    free(fail);
    return n % p == 0 ? p : n;
}
